// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role, address actor) public {
        // The construction grants TIMELOCK_ADMIN_ROLE to the timelock contract itself,
        // so for ANY (role, actor) admissible input, hasRole(TIMELOCK_ADMIN_ROLE, address(c))
        // must truthfully report that existing membership.
        vm.assume(actor != address(0));
        assertTrue(c.hasRole(c.TIMELOCK_ADMIN_ROLE(), address(c)));
    }
}
